import matplotlib.pyplot as plt
ROOT=Path(__file__).resolve().parent

def main():
 m=ROOT/'mechanistic';t=pd.read_csv(m/'ten_target_summary.tsv',sep='\t').set_index('target');p=pd.read_csv(m/'per_pose.tsv',sep='\t');w=pd.read_csv(m/'four_window_summary.tsv',sep='\t');lys=pd.read_csv(m/'per_lysine_equal_pose_summary.tsv',sep='\t');delta=pd.read_csv(m/'legacy_delta50_audit.tsv',sep='\t');refs=pd.read_csv(m/'reference_sensitivity.tsv',sep='\t');unknown=pd.read_csv(ROOT/'unknown_prediction_summary.tsv',sep='\t');order=['ABL1','AXL','DDR2','EPHA2','EPHB2','MAPK14_full','MET','RIPK2_full','SIK3_full','RPS6KB2_full'];t=t.loc[order];coverage=pd.read_csv(m/'modeled_protein_coverage.tsv',sep='\t');numbering=json.loads((ROOT/'validation/residue_numbering.json').read_text());assert numbering['status']=='PASS';colors=['#e45756' if t.loc[x,'group']=='non_degrader' else '#777777' if t.loc[x,'group']=='unknown' else '#4c78a8' for x in order]
 fig,ax=plt.subplots(1,2,figsize=(13,6));y=np.arange(10)
 for col,label in [('bridge_fraction','True-VHL bridge'),('any_lysine_reachable20_fraction','Any lysine within20A'),('joint_bridge_productive_fraction','Exposed/reachable/clear/bridging')]:ax[0].plot(t[col]*100,y,'o-',label=label)
 ax[0].set(yticks=y,yticklabels=order,xlabel='Mean fraction of frames (%)',title='Same frozen geometry rules, all targets');ax[0].invert_yaxis();ax[0].legend(fontsize=8)
 heat=w.pivot(index='target',columns='window',values='joint_bridge_productive_fraction').loc[order].to_numpy()*100;im=ax[1].imshow(heat,aspect='auto',cmap='viridis',vmin=0);ax[1].set(yticks=y,yticklabels=order,xticks=range(4),xticklabels=['0–5','5–10','10–15','15–20'],xlabel='MD window (ns)',title='Productive + bridging (% frames)');fig.colorbar(im,ax=ax[1]);fig.tight_layout()
 for ext in ['png','pdf']:fig.savefig(ROOT/('ten_target_geometry.'+ext),dpi=220)
 plt.close(fig)
 fig,ax=plt.subplots(figsize=(11,5));series=[p.loc[p.target==x,'joint_bridge_productive_fraction'].to_numpy()*100 for x in order];bp=ax.boxplot(series,tick_labels=order,patch_artist=True)
 for b,c in zip(bp['boxes'],colors):b.set_facecolor(c)
 ax.tick_params(axis='x',rotation=45);ax.set(ylabel='Productive + bridging frames (%)',title='Variation across retained MD poses; poses are not biological replicates');fig.tight_layout()
 for ext in ['png','pdf']:fig.savefig(ROOT/('pose_spread.'+ext),dpi=220)
 plt.close(fig)
 # Compare held-out labelled score distributions with prediction-only distributions.
 robust=Path('/home/ayushregmibagale/10PROTAC-MD/SJF8240_renanalysis2/robustness_followup_v1');records=json.loads((robust/'completion.json').read_text());rows=[]
 for r in records:
  for target in [r['positive'],r['negative']]:rows.append({'target':target,'variant':r['variant'],'seed':r['base_seed'],'score':r['scores'][target],'evaluation':'heldout_labelled'})
 df=pd.DataFrame(rows);known=df.groupby(['target','variant']).agg(mean_score=('score','mean'),min_score=('score','min'),max_score=('score','max'),scores=('score','size')).reset_index();known.to_csv(ROOT/'known_target_heldout_scores.tsv',sep='\t',index=False)
 table=t[['group','poses','modeled_POI_residues','lysines','bridge_fraction','any_lysine_reachable20_fraction','any_lysine_exposed_reachable20_fraction','scaffold_compatible_fraction','joint_bridge_productive_fraction','median_VHL_anchor_RMSD_A']].reset_index();table.to_csv(ROOT/'TEN_TARGET_OVERVIEW.tsv',sep='\t',index=False)
 evidence=[]
 for target in ['ABL1','AXL','MAPK14_full','RIPK2_full']:
  r=t.loc[target];evidence.append(f"- {target}: bridge {100*r.bridge_fraction:.1f}%; at least one lysine within20A {100*r.any_lysine_reachable20_fraction:.2f}%; exposed + within20A {100*r.any_lysine_exposed_reachable20_fraction:.2f}%; scaffold compatible {100*r.scaffold_compatible_fraction:.1f}%; all conditions including bridging {100*r.joint_bridge_productive_fraction:.2f}%.")
 refspan=refs.groupby('target').joint_bridge_productive_fraction.agg(['min','max']).reset_index();refspan.to_csv(m/'reference_range.tsv',sep='\t',index=False)
 metric=pd.read_csv(m/'descriptive_geometry_AUROCs.tsv',sep='\t');checks=json.loads((ROOT/'validation/feature_matching.json').read_text());ind=json.loads((ROOT/'validation/independent_geometry.json').read_text());cpu=json.loads((ROOT/'validation/unknown_CPU_replay.json').read_text());assert checks['status']==ind['status']==cpu['status']=='PASS'
 # Eight-target score reproduction is checked against the archived native reference result.
 old=pd.read_csv('/home/ayushregmibagale/10PROTAC-MD/SJF8240_renanalysis2/native_catalytic_validation_v2/results/primary_target_scores.tsv',sep='\t').set_index('poi');maxerr=max(abs(t.loc[x,'joint_bridge_productive_fraction']-old.loc[x,'joint_bridge_productive_fraction']) for x in old.index);assert maxerr<1e-12
 historical=pd.read_csv('/home/ayushregmibagale/10PROTAC-MD/SJF8240_reanalysis/full_frame_e2_delta50_v1/results/target_summary.tsv',sep='\t');historical=historical[historical.variant=='corrected_geometry_true_VHL'].set_index('poi');deltaidx=delta.set_index('target');delta_error=max(abs(deltaidx.loc[x,'positive_delta_fraction']-historical.loc[x,'fraction_positive']) for x in historical.index);assert delta_error<1e-12
 lines=['# Ten-target mechanistic audit and frozen-model predictions','', '## Main findings','', 'The matching input gap for SIK3/RPS6KB2 is now resolved. Both are scored above0.5 by every one of the60 frozen catalytic-feature models (five seeds × twelve matched folds). Mean catalytic scores: SIK3 0.809841; RPS6KB2 0.805951. The zero-padded control also predicts both above0.5 in all60 models. These are classifier outputs, not calibrated degradation probabilities or experimental labels. The model fails to reject known ABL1/AXL negatives, so the unknown calls have weak biological support.','', 'The geometric discrimination problem is present in the measured signal itself: ABL1 can satisfy the frozen catalytic geometry while confirmed degraders such as MAPK14 and RIPK2 seldom do. Successful numerical checks do not make this a physically validated catalytic model.','', *evidence,'', 'The eight preselected control poses reproduce every compared archived base/native feature array exactly (maximum error0). Independent geometry checks on12 preselected raw frames across ABL1,AXL,SIK3,RPS6KB2 passed using MDAnalysis unwrap,Bio.SVDSuperimposer and brute-force SciPy distances/overlap. These checks share the imaging convention; they do not validate the biological pose ensemble, catalytic-reference ensemble coverage, lysine rotamers or the cutoff choice.','', '## Step1 — Source and identity audit','', 'Retained existing trajectories only; no docking, MD, minimization, model fitting, label changes or threshold tuning. Core141 poses reused; all33 unknown poses extracted (15 SIK3,18 RPS6KB2). Each has201frames over0–20ns. Topology hashes bind independently sequence-identified ELOB(chainA),ELOC(B),trueVHL(C),POI(D). The full name in a target directory does not imply a full-length protein: see modeled residue and lysine counts in the overview. Missing residues/lysines are outside this test, not negatives. Historical molecule provenance retained; supplier equivalence is not claimed.','', '### Protein coverage and numbering','',coverage.to_markdown(index=False),'', 'SIK3 is a241residue fragment of a1321residue canonical sequence; RPS6KB2 is241/482. The directory suffix_full does not establish complete modeled protein coverage. Lysine tables keep topology_resid/lysine_resid and add canonical_resid only for unambiguous sequence-matched lysines. Observed DDR2 and MAPK14 sequence mismatches and unaligned/tag residues are retained in construct_sequence_differences.tsv; they are not silently repaired. In particular a canonical DDR2 lysine maps to observed glutamate, so the modeled lysine inventory differs from the canonical sequence. Intent or experimental relevance of those sequence differences is not inferred.','', '## Step2 — Matching inputs','', 'Original29 node features and contact edges follow the archived four-window implementation, including41 sampled frames at0.5ns,heavy-atom Shrake–Rupley SASA,legacy E2 ensemble and equal pose weighting. Five new lysine-node features use201frames at0.1ns and the exact archived native-reference definitions. Four graphs were prepared: native and zero-padded variants for each unknown,34features. Model architecture and trained weights were unchanged. Original dynamic graph.npz files were not rebuilt or overwritten.','', '## Step3 — Frozen prediction-only inference','', unknown.to_markdown(index=False),'', '120 existing checkpoints × two unknowns =240 predictions. Each was replayed with a fresh model instance; both original held-out scores per checkpoint were also reproduced (240 reference replays). Unknowns never entered training, threshold selection or AUROC calculations. Correlated folds and seeds do not create60 independent biological predictions. Thresholds come from the earlier training-only calibration; fixed0.5 and training-only decisions are both saved.','', '## Step4 — Mechanistic target comparison','',table.to_markdown(index=False),'', 'Fractions are means over frames within each pose, then equal means over poses. Any-lysine productive fraction is an OR over lysines per frame, not the mean lysine fraction used by the simple baseline. Productive here means distance<=20A, NZ sampled-surface exposure>=0.1 and whole-target scaffold overlap<=0.8A; joint adds simultaneous trueVHL/ligand and POI/ligand distances<5A. Deposited8R5H SY8_C3 is a crosslink surrogate, not a native Gly76 carbonyl. This is geometric access, not demonstrated ubiquitin transfer.','', '### Which gate removes access?','', 'Compare reachable20 with exposed+reachable20, then scaffold compatibility and joint bridging. The scaffold-compatible fraction is high for the known targets, so blanket steric exclusion is not the sole cause of failure. ABL1 retains geometric access despite being a non-degrader; MAPK14 frequently bridges but almost never brings a modeled lysine near the chosen donor surrogate. Pose- and lysine-level tables identify the exact sites; this cannot be repaired by assuming every bridged binder degrades.','', '### Time and pose dependence','', 'Four-window and per-pose results are saved separately with top five modeled lysines per target. Pose percentile ranges describe variation across retained docking starts; they are not biological confidence intervals. Consecutive-sample counts describe0.1ns sampled observations, not an experimentally validated catalytic residence time.','', '### Reference dependence','',refspan.to_markdown(index=False),'', 'Range spans the three archived reference constructions and VHL/ELOC alignment choices. These alternatives are sensitivity analyses, not independent physical replicates; no reference was selected against target labels. Median/max alignment RMSDs are recorded for each pose/reference.','', '## Step5 — Legacy50A signal checked separately','',delta.to_markdown(index=False),'', 'Source inspection of20_per_lysine_e2_distance.py corrects the earlier verbal explanation: original reach_50A is the fraction of frames with a lysine minimum distance to any E2 ensemble point<50A. It does not count the fraction of E2 points within50A. The table above reproduces that frame-access definition using corrected ligand-connected imaging and trueVHL bridging. Delta is bridge-state mean minus nonbridge-state mean within each pose, then equal averaging over poses with both states present. Undefined-state poses are excluded with counts retained. The corrected original eight-target result is reproduced; the original clean separation is not recovered.','', 'A separate new sensitivity measure counts the fraction of663 E2 points within50A per frame; it is explicitly named ensemble_point_reach50 and saved in separate columns/tables. It is not presented as reproduction of the historical metric. Lysines/frames are not independent biological replicates; no inflated per-lysine p-value is used. Neither legacy50A measure is interchangeable with the native-reference20A catalytic feature.','', '## Step6 — Eight-labelled-target descriptive scores','',metric.to_markdown(index=False),'', 'SIK3/RPS6KB2 excluded from all performance metrics. EPHA2 remains label1. These are retrospective descriptive scores from eight independent proteins, not independent test-set validation. The previously completed five-seed GNN study remains unchanged (control meanAUROC0.733; catalytic0.667).','', '## Conclusion and remaining limits','', 'The new audit supports numerical consistency, not a reliable degradation classifier. ABL1/AXL failures cannot be dismissed as a simple wrong-chain or serialization bug in these checked calculations. Ensemble/reference incompleteness, the historical molecule, missing protein regions, lysine sidechain sampling, coarse exposure/steric gates and biology beyond contact geometry remain possible causes. More tuning on eight labelled targets cannot resolve those limitations. Experimental degradation tests for SIK3/RPS6KB2 would provide new evidence; current predictions must not become labels.','', '## Saved material','', 'Numbered scripts, source snapshots, manifests, unknown graphs, per-frame packets, pose/lysine/window tables, sensitivity tables, figures, CPU receipts and this Markdown/Word report are saved in this study folder. Original inputs and model checkpoints are referenced by hashes and remain unchanged.']
 (ROOT/'FINDINGS.md').write_text('\n'.join(lines)+'\n')
 from docx import Document
 d=Document();d.add_heading('Ten-target mechanistic audit',0)
 for line in lines:
  if line:d.add_paragraph(line)
 d.add_picture(str(ROOT/'ten_target_geometry.png'),width=__import__('docx').shared.Inches(6.3));d.add_picture(str(ROOT/'pose_spread.png'),width=__import__('docx').shared.Inches(6.3));d.save(ROOT/'FINDINGS.docx')
 status={'status':'COMPLETE','known_targets':8,'unknown_targets':2,'retained_poses':174,'frames_per_pose':201,'unknown_input_graphs':4,'frozen_models':120,'new_training':False,'unknown_scores':240,'unknown_labels_used':False,'EPHA2_label':1,'archived_target_score_max_error':float(maxerr),'historical_corrected_positive_delta_fraction_max_error':float(delta_error),'feature_matching':'PASS','independent_geometry':'PASS','CPU_replay':'PASS','residue_numbering':'PASS','physical_catalysis_validated':False};(ROOT/'COMPLETION.json').write_text(json.dumps(status,indent=2));print(json.dumps(status,indent=2))
if __name__=='__main__':main()
